#!/usr/bin/env node
// Per-agent scope for hooks shipped as a GLOBAL plugin (minimax-cli).
//
// mcode discovers every Claude-format plugin under $MINIMAX_DATA_DIR/plugins
// as installed + enabled, for every run on the host. Each Marveen agent's
// hooks live in their own plugin, so without a scope every mcode agent would
// also run every other agent's hooks (and a leftover smoke-test plugin runs
// for the real agents). This wrapper runs the hook only when the call belongs
// to the agent it was generated for.
//
// Usage (generated by minimax-cli prepareMinimaxBundle):
//   node scope-hook.mjs b64:<agent dir> b64:<original hook command>
//
// Decision: payload.cwd present and OUTSIDE the agent dir -> not ours, exit 0
// (silent pass-through). Anything else -- cwd inside, or no cwd in the payload
// -- runs the hook: when in doubt the gate runs (fail toward enforcement).
// Stdin is forwarded unchanged; stdout/stderr/exit code come back unchanged.

import { spawnSync } from 'node:child_process'
import { readFileSync, realpathSync } from 'node:fs'
import { sep } from 'node:path'

function decode(arg) {
  if (!arg || !arg.startsWith('b64:')) return null
  try { return Buffer.from(arg.slice(4), 'base64').toString('utf-8') } catch { return null }
}

function canon(p) { try { return realpathSync(p) } catch { return p } }

export function belongsTo(agentDir, payloadCwd) {
  if (typeof payloadCwd !== 'string' || !payloadCwd) return true
  const a = canon(agentDir).replace(/\/+$/, '')
  const c = canon(payloadCwd).replace(/\/+$/, '')
  return c === a || c.startsWith(a + sep)
}

function main() {
  const agentDir = decode(process.argv[2])
  const command = decode(process.argv[3])
  if (!agentDir || !command) {
    process.stderr.write('scope-hook: usage b64:<agentDir> b64:<command> -- blocking (fail closed)\n')
    process.exit(2)
  }
  let raw = ''
  try { raw = readFileSync(0, 'utf-8') } catch { raw = '' }
  let cwd
  try { cwd = JSON.parse(raw)?.cwd } catch { cwd = undefined }
  if (!belongsTo(agentDir, cwd)) process.exit(0)
  const res = spawnSync('/bin/sh', ['-c', command], { input: raw, encoding: 'utf-8', env: process.env, maxBuffer: 8 * 1024 * 1024 })
  if (res.stdout) process.stdout.write(res.stdout)
  if (res.stderr) process.stderr.write(res.stderr)
  if (res.error) { process.stderr.write(`scope-hook: failed to run hook: ${res.error.message}\n`); process.exit(2) }
  process.exit(res.status ?? 2)
}

if (process.argv[1] && process.argv[1].endsWith('scope-hook.mjs')) main()
